# How much of the icon the logo fills. Bigger number = bigger logo on home screen.
SQUARE_FILL = 0.88   # normal launcher icon
ROUND_FILL = 0.66    # round icon (circle crop cuts corners, so keep it smaller)
BG_COLOR = (255, 255, 255, 255)


def load_logo():
    data = base64.b64decode("".join(LOGO_PNG_B64.split()))
    return Image.open(io.BytesIO(data)).convert("RGBA")


def _place(logo, size, fill):
    mark = logo.copy()
    target = int(size * fill)
    mark = mark.resize((target, target), Image.Resampling.LANCZOS)
    layer = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    layer.alpha_composite(mark, ((size - target) // 2, (size - target) // 2))
    return layer


def _supersample(draw_fn, size):
    """Draw at 4x then shrink for smooth edges."""
    big = size * 4
    img = draw_fn(big)
    return img.resize((size, size), Image.Resampling.LANCZOS)


def make_launcher(logo, size):
    def draw(s):
        bg = Image.new("RGBA", (s, s), BG_COLOR)
        mask = Image.new("L", (s, s), 0)
        ImageDraw.Draw(mask).rounded_rectangle(
            (0, 0, s - 1, s - 1), radius=int(s * 0.22), fill=255
        )
        out = Image.new("RGBA", (s, s), (0, 0, 0, 0))
        out.paste(bg, (0, 0), mask)
        out.alpha_composite(_place(logo, s, SQUARE_FILL))
        return out

    return _supersample(draw, size)


def make_launcher_round(logo, size):
    def draw(s):
        mask = Image.new("L", (s, s), 0)
        ImageDraw.Draw(mask).ellipse((0, 0, s - 1, s - 1), fill=255)
        out = Image.new("RGBA", (s, s), (0, 0, 0, 0))
        out.paste(Image.new("RGBA", (s, s), BG_COLOR), (0, 0), mask)
        out.alpha_composite(_place(logo, s, ROUND_FILL))
        return out

    return _supersample(draw, size)


def make_notification_icon(logo, size=96):
    # Android notification small icons must be a white silhouette on transparency.
    alpha = logo.getchannel("A").point(lambda v: 255 if v > 90 else 0)
    bbox = alpha.getbbox()
    if bbox:
        alpha = alpha.crop(bbox)

    pad = int(size * 0.10)
    alpha.thumbnail((size - 2 * pad, size - 2 * pad), Image.Resampling.LANCZOS)
    canvas = Image.new("L", (size, size), 0)
    canvas.paste(alpha, ((size - alpha.width) // 2, (size - alpha.height) // 2))

    icon = Image.new("RGBA", (size, size), (255, 255, 255, 0))
    icon.putalpha(canvas)
    return icon


def save_all(res_dir):
    res = Path(res_dir)
    logo = load_logo()

    launcher_sizes = {
        "mipmap-mdpi": 48,
        "mipmap-hdpi": 72,
        "mipmap-xhdpi": 96,
        "mipmap-xxhdpi": 144,
        "mipmap-xxxhdpi": 192,
    }

    for folder, size in launcher_sizes.items():
        d = res / folder
        d.mkdir(parents=True, exist_ok=True)
        make_launcher(logo, size).save(d / "ic_launcher.png", optimize=True)
        make_launcher_round(logo, size).save(d / "ic_launcher_round.png", optimize=True)

    # The notification Dart code uses @drawable/ic_stat_farmbook.
    drawable = res / "drawable"
    drawable.mkdir(parents=True, exist_ok=True)
    make_notification_icon(logo, 96).save(drawable / "ic_stat_farmbook.png", optimize=True)

    # 512px master PNG for any future tooling.
    make_launcher(logo, 512).save(res / "farmbook_logo.png", optimize=True)

    print("FarmBook icons generated successfully.")
    print("Launcher: mipmap-*/ic_launcher.png + ic_launcher_round.png")
    print("Notification: drawable/ic_stat_farmbook.png")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python3 make_icons.py android/app/src/main/res")
    save_all(sys.argv[1])
